<?php
require dirname(__DIR__).'/app/bootstrap.php';$title='My reservations — EAD Stay';$error='';$bookings=[];$rooms=rooms();$extras=services();
try {
    if($_SERVER['REQUEST_METHOD']==='POST') {
        if(!hash_equals($_SESSION['csrf'],scalar($_POST,'csrf'))){http_response_code(403);$error='Your session expired. Refresh and try again.';}
        elseif(scalar($_POST,'action')==='cancel') {db()->prepare('UPDATE bookings SET status="cancelled" WHERE id=? AND owner=? AND status="confirmed"')->execute([scalar($_POST,'id'),$owner]);header('Location: booking-list.php',true,303);exit;}
        else {http_response_code(422);$error='That action is not supported.';}
    }
    $statement=db()->prepare('SELECT * FROM bookings WHERE owner=? ORDER BY created_at DESC,id DESC');$statement->execute([$owner]);$bookings=$statement->fetchAll();
} catch(Throwable $exception){error_log($exception->getMessage());http_response_code(503);$error='Reservations are temporarily unavailable. Please try again.';}
$ref=scalar($_GET,'ref');$confirmed=in_array($ref,array_column($bookings,'id'),true);include 'header.php'; ?>
<main id="main" class="wrap reservation-main"><div class="section-heading"><div><p class="eyebrow">SOMETHING TO LOOK FORWARD TO</p><h1>Your next<br><em>chapter.</em></h1></div><a class="button" href="booking.php">Plan another stay ↗</a></div><?php if($error): ?><div role="alert" class="feedback error"><?= e($error) ?></div><?php endif ?><?php if($confirmed): ?><div role="status" class="feedback success"><strong>You're all set — your demo stay is saved.</strong><p>Reference <?= e($ref) ?>. No payment was taken and no real room was reserved.</p></div><?php endif ?><p class="form-hint">Only reservations made in this browser are shown. Demo identity expires after 30 days.</p>
<?php if(!$bookings&&!$error): ?><div class="empty-state"><span>✳</span><h2>Your next escape<br>starts here.</h2><p>No reservations just yet. Pick a room and make a little time for yourself.</p><a class="button" href="index.php#rooms">Discover our rooms ↗</a></div><?php endif ?>
<?php foreach($bookings as $booking): $room=$rooms[$booking['room']];?><article class="reservation-card"><img src="assets/img/<?= e($room['image']) ?>" alt="<?= e($room['name']) ?>"><div class="reservation-info"><div class="reservation-top"><span class="eyebrow"><?= e($booking['id']) ?></span><span class="status-pill <?= e($booking['status']) ?>"><?= $booking['status']==='confirmed'?'Demo confirmed':'Cancelled' ?></span></div><h2><?= e($room['name']) ?></h2><p><?= e($booking['name']) ?> · <?= $booking['guests'] ?> guest(s)</p><div class="reservation-dates"><div><small>CHECK-IN</small><strong><?= date('d M Y',strtotime($booking['checkin'])) ?></strong></div><span>→</span><div><small>CHECK-OUT</small><strong><?= date('d M Y',strtotime($booking['checkout'])) ?></strong></div><div><small>YOUR STAY</small><strong><?= $booking['nights'] ?> night(s)</strong></div></div><details><summary>Reservation details</summary><p><?= e($booking['email']) ?> · <?= e($booking['phone']) ?></p><p>Extras: <?= e(implode(', ',array_map(fn($id)=>$extras[$id]['name'],json_decode($booking['services'],true)))?:'None') ?></p><p>Room <?= usd($room['price']) ?> × <?= $booking['nights'] ?> night(s). Extras charged once per stay.</p></details></div><div class="reservation-actions"><small>DEMO TOTAL</small><strong><?= usd($booking['total']) ?></strong><?php if($booking['status']==='confirmed'): ?><form method="post" data-cancel><input type="hidden" name="csrf" value="<?= e($_SESSION['csrf']) ?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?= e($booking['id']) ?>"><button type="submit" class="cancel-button">Cancel reservation</button></form><?php endif ?></div></article><?php endforeach ?></main><?php include 'footer.php'; ?>
